	end

/*****************<-------butterfly control------>************************/

	always@(posedge clk) begin
		if(rst == 1)begin
			butterfly_enable	<=	0;
		end else begin
			if(r_state_16 == STATE_START | r_state_16 == STATE_PROCESSING | start16 == 1) begin
				butterfly_enable	<=	1;
			end else if (r_state_16== STATE_END) begin
				butterfly_enable	<=	0;
			end else begin
