			end
		end
	end

	always@(posedge clk) begin
		if(rst == 1)begin
			S16_counter	<=	0;
		end else begin
			if(r_state_16 == STATE_START | r_state_16 == STATE_PROCESSING) begin
				S16_counter	<=	S16_counter + 1;
